import type { Template } from '@/modules/lfk-templates/types';
import { EMPTY_LFK_TEMPLATE_USAGE_SNAPSHOT } from '@/modules/lfk-templates/types';
import { TemplateEditor } from './TemplateEditor';

vi.mock('@dnd-kit/core', () => ({
