    assignmentSource: 'doctor',
    title: 'Программа деталь',
    status: 'active',
    createdAt: now,
    updatedAt: now,
    patientPlanLastOpenedAt: null,
    stages: [
      {
        id: stageId,
        instanceId: '11111111-1111-4111-8111-111111111111',
        sourceStageId: null,
        title: 'Этап 1',
        description: null,
        sortOrder: 1,
        localComment: null,
        skipReason: null,
        status: 'in_progress',
        startedAt: null,
        goals: null,
        objectives: null,
        expectedDurationDays: null,
        expectedDurationText: null,
        groups: [],
