          {
            id: '33333333-3333-4333-8333-333333333333',
            stageId,
            itemType: 'recommendation',
            itemRefId: '44444444-4444-4444-8444-444444444444',
            sortOrder: 0,
            comment: null,
            localComment: null,
            settings: null,
            snapshot: {},
            completedAt: null,
            isActionable: true,
