        return Promise.resolve({
          jobKey: OPERATOR_WEB_PUSH_ONLY_REMINDER_TICK_JOB_KEY,
          jobFamily: OPERATOR_REMINDERS_JOB_FAMILY,
          lastStatus: 'success',
