const presignMock = vi.fn();
const recordPlaybackResolutionStatMock = vi.fn((..._args: unknown[]) => Promise.resolve());
const recordPlaybackResolutionEventMock = vi.fn((..._args: unknown[]) => Promise.resolve());
const recordPlaybackUserVideoFirstResolveMock = vi.fn((..._args: unknown[]) =>
  Promise.resolve(false),
);
const requirePatientApiBusinessAccessMock = vi.fn();
const requireDoctorWorkspaceApiContextMock = vi.fn();

vi.mock('@/config/env', () => ({
  env: { DATABASE_URL: 'postgres://x/bersoncarebot_test' },
}));

vi.mock('@/modules/auth/service', () => ({
  getCurrentSession: () => getSessionMock(),
}));

vi.mock('@/app-layer/guards/requireRole', () => ({
  requireDoctorWorkspaceApiContext: () => requireDoctorWorkspaceApiContextMock(),
  requirePatientApiBusinessAccess: () => requirePatientApiBusinessAccessMock(),
}));

vi.mock('@/app-layer/guards/doctorWorkspacePrincipal', () => ({
  withDoctorWorkspacePrincipal: (_ctx: unknown, fn: () => unknown) => fn(),
}));

vi.mock('@/modules/system-settings/configAdapter', () => ({
  getPatientRuntimeBool: (...a: unknown[]) => getConfigBoolMock(...a),
  getPatientRuntimeValue: (...a: unknown[]) => getConfigValueMock(...a),
}));

vi.mock('@/app-layer/media/videoPresignTtl', () => ({
  getVideoPresignTtlSeconds: vi.fn(() => Promise.resolve(3600)),
}));

vi.mock('@/app-layer/media/s3MediaStorage', () => ({
  getMediaRowForPlayback: (...a: unknown[]) => getRowMock(...a),
  getMediaAccessRow: (...a: unknown[]) => getAccessRowMock(...a),
}));
vi.mock('@/app-layer/media/resolvePlatformLfkMediaAccess', () => ({
  resolvePlatformLfkMediaAccess: vi.fn(async () => false),
}));

vi.mock('@/app-layer/media/s3Client', () => ({
  presignGetUrl: (...a: unknown[]) => presignMock(...a),
}));

vi.mock('@/app-layer/media/playbackStatsHourly', () => ({
  recordPlaybackResolutionStat: (...a: unknown[]) => recordPlaybackResolutionStatMock(...a),
}));

vi.mock('@/app-layer/media/playbackResolutionEvents', () => ({
  recordPlaybackResolutionEvent: (...a: unknown[]) => recordPlaybackResolutionEventMock(...a),
}));

vi.mock('@/app-layer/media/playbackUserVideoFirstResolve', () => ({
  recordPlaybackUserVideoFirstResolve: (...a: unknown[]) =>
    recordPlaybackUserVideoFirstResolveMock(...a),
}));

import { GET } from './route';
import { getVideoPresignTtlSeconds } from '@/app-layer/media/videoPresignTtl';

const mid = '00000000-0000-4000-8000-000000000099';
const patientSession = {
  user: { userId: 'u1', role: 'client' as const, displayName: 'U', bindings: {} },
};
const adminSession = {
  user: { userId: 'a1', role: 'admin' as const, displayName: 'A', bindings: {} },
};

function videoRow(over: Partial<Record<string, unknown>> = {}) {
  return {
    id: mid,
    mime_type: 'video/mp4',
    s3_key: `media/${mid}/v.mp4`,
    stored_path: `media/${mid}/v.mp4`,
    video_processing_status: 'ready',
    hls_master_playlist_s3_key: `media/${mid}/hls/master.m3u8`,
    poster_s3_key: `media/${mid}/poster/poster.jpg`,
    video_duration_seconds: 60,
    available_qualities_json: [
      { label: '720p', height: 720, path: '720p/index.m3u8', bandwidth: 2800000 },
    ],
    video_delivery_override: null,
    usage_purpose: null,
    uploaded_by: 'u1',
    ...over,
  };
}

describe('GET /api/media/[id]/playback', () => {
  beforeEach(() => {
    getSessionMock.mockReset();
    getConfigBoolMock.mockReset();
    getConfigValueMock.mockReset();
    getRowMock.mockReset();
    getAccessRowMock.mockReset();
    requirePatientApiBusinessAccessMock.mockReset();
    requireDoctorWorkspaceApiContextMock.mockReset();
    presignMock.mockReset();
    recordPlaybackResolutionStatMock.mockClear();
    recordPlaybackResolutionEventMock.mockClear();
    recordPlaybackUserVideoFirstResolveMock.mockClear();
    getSessionMock.mockResolvedValue(patientSession);
    requirePatientApiBusinessAccessMock.mockResolvedValue({ ok: true, session: patientSession });
    requireDoctorWorkspaceApiContextMock.mockResolvedValue({
      ok: true,
      ctx: {
        organizationId: '10000000-0000-4000-8000-000000000001',
        session: adminSession,
      },
    });
    getAccessRowMock.mockResolvedValue({
      usage_purpose: null,
      uploaded_by: 'u1',
      mime_type: 'video/mp4',
    });
    getConfigBoolMock.mockResolvedValue(true);
    getConfigValueMock.mockResolvedValue('mp4');
    presignMock.mockResolvedValue('https://signed.example/master');
    vi.mocked(getVideoPresignTtlSeconds).mockResolvedValue(3600);
  });

  it('returns 401 when unauthenticated', async () => {
    getSessionMock.mockResolvedValue(null);
    getAccessRowMock.mockResolvedValue({
      usage_purpose: null,
      uploaded_by: 'u1',
      mime_type: 'video/mp4',
    });
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(401);
  });

  it('returns 503 when video_playback_api_enabled is false', async () => {
    getConfigBoolMock.mockResolvedValue(false);
    getRowMock.mockResolvedValue(videoRow());
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(503);
    const b = (await res.json()) as { error?: string };
    expect(b.error).toBe('feature_disabled');
  });

  it('allows only the exact local TEST fixture when the global playback flag is absent', async () => {
    getConfigBoolMock.mockResolvedValue(false);
    getAccessRowMock.mockResolvedValue({
      usage_purpose: null,
      uploaded_by: 'u1',
      mime_type: 'image/svg+xml',
      stored_path: '/test-fixtures/saas-exercise.svg',
      s3_key: null,
    });
    getRowMock.mockResolvedValue(
      videoRow({
        mime_type: 'image/svg+xml',
        s3_key: null,
        stored_path: '/test-fixtures/saas-exercise.svg',
        video_processing_status: null,
      }),
    );

    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });

    expect(res.status).toBe(200);
    const body = (await res.json()) as { delivery?: string; mp4?: { url?: string } };
    expect(body.delivery).toBe('file');
    expect(body.mp4?.url).toBe(`/api/media/${mid}`);
  });

  it('returns 404 when media row missing', async () => {
    getAccessRowMock.mockResolvedValue(null);
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(404);
  });

  it('returns 403 for submission media owned by another patient', async () => {
    getAccessRowMock.mockResolvedValue({
      usage_purpose: 'program_item_submission',
      uploaded_by: 'other-patient',
      mime_type: 'video/mp4',
    });
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(401);
    expect(getRowMock).not.toHaveBeenCalled();
  });

  it('non-video → delivery file, no presign', async () => {
    getRowMock.mockResolvedValue({
      ...videoRow(),
      mime_type: 'image/png',
      s3_key: null,
    });
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(200);
    const b = (await res.json()) as { delivery?: string; hls?: unknown };
    expect(b.delivery).toBe('file');
    expect(b.hls).toBeNull();
    expect(presignMock).not.toHaveBeenCalled();
    expect(getRowMock).toHaveBeenCalledWith(mid, {
      allowLocalSaasTestFixture: true,
      allowPlatformBase: false,
    });
  });

  it('video HLS not ready → delivery mp4, hls null', async () => {
    getConfigValueMock.mockResolvedValue('hls');
    getRowMock.mockResolvedValue(
      videoRow({
        video_processing_status: 'processing',
        hls_master_playlist_s3_key: null,
        poster_s3_key: null,
      }),
    );
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(200);
    const b = (await res.json()) as { delivery?: string; hls?: unknown; fallbackUsed?: boolean };
    expect(b.delivery).toBe('mp4');
    expect(b.hls).toBeNull();
    expect(b.fallbackUsed).toBe(true);
    expect(presignMock).not.toHaveBeenCalled();
  });

  it('video HLS ready + auto default → proxy master URL + presign poster', async () => {
    getConfigValueMock.mockResolvedValue('auto');
    getRowMock.mockResolvedValue(videoRow());
    presignMock.mockResolvedValueOnce('https://signed.example/poster.jpg');
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(200);
    const b = (await res.json()) as {
      delivery?: string;
      hls?: { masterUrl?: string };
      posterUrl?: string;
    };
    expect(b.delivery).toBe('hls');
    expect(b.hls?.masterUrl).toBe(`/api/media/${mid}/hls/master.m3u8`);
    expect(b.posterUrl).toBe('https://signed.example/poster.jpg');
    expect(presignMock).toHaveBeenCalledTimes(1);
    expect(recordPlaybackResolutionStatMock).toHaveBeenCalledWith({
      userId: 'u1',
      mediaId: mid,
      delivery: 'hls',
      fallbackUsed: false,
    });
    expect(recordPlaybackResolutionEventMock).toHaveBeenCalledTimes(1);
    expect(recordPlaybackUserVideoFirstResolveMock).toHaveBeenCalledTimes(1);
  });

  it('presign uses TTL from getVideoPresignTtlSeconds for poster only', async () => {
    vi.mocked(getVideoPresignTtlSeconds).mockResolvedValue(7200);
    getConfigValueMock.mockResolvedValue('auto');
    getRowMock.mockResolvedValue(videoRow());
    presignMock.mockResolvedValueOnce('https://signed.example/poster.jpg');
    await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(presignMock).toHaveBeenCalledTimes(1);
    expect(presignMock).toHaveBeenCalledWith(expect.stringContaining('poster'), 7200);
  });

  it('presign poster fails but HLS ready → hls with proxy master and null posterUrl', async () => {
    getConfigValueMock.mockResolvedValue('auto');
    getRowMock.mockResolvedValue(videoRow());
    presignMock.mockRejectedValueOnce(new Error('poster_sign_failed'));
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(200);
    const b = (await res.json()) as {
      delivery?: string;
      hls?: { masterUrl?: string };
      posterUrl?: string | null;
    };
    expect(b.delivery).toBe('hls');
    expect(b.hls?.masterUrl).toBe(`/api/media/${mid}/hls/master.m3u8`);
    expect(b.posterUrl == null).toBe(true);
    expect(presignMock).toHaveBeenCalledTimes(1);
  });

  it('ignores ?prefer= for non-admin', async () => {
    getConfigValueMock.mockResolvedValue('mp4');
    getRowMock.mockResolvedValue(videoRow({ poster_s3_key: null }));
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback?prefer=hls`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(200);
    const b = (await res.json()) as { delivery?: string };
    expect(b.delivery).toBe('mp4');
    expect(presignMock).not.toHaveBeenCalled();
  });

  it('applies ?prefer=hls for admin when HLS ready', async () => {
    getSessionMock.mockResolvedValue(adminSession);
    getConfigValueMock.mockResolvedValue('mp4');
    getRowMock.mockResolvedValue(videoRow());
    presignMock.mockResolvedValueOnce('https://signed.example/p');
    const res = await GET(new Request(`http://localhost/api/media/${mid}/playback?prefer=hls`), {
      params: Promise.resolve({ id: mid }),
    });
    expect(res.status).toBe(200);
    const b = (await res.json()) as { delivery?: string };
    expect(b.delivery).toBe('hls');
    expect(recordPlaybackResolutionStatMock).not.toHaveBeenCalled();
    expect(recordPlaybackResolutionEventMock).not.toHaveBeenCalled();
    expect(recordPlaybackUserVideoFirstResolveMock).not.toHaveBeenCalled();
  });
});

