    expect(archiveTariffMock).not.toHaveBeenCalled();
  });

  it('passes a typed exact-organization quota override to the platform service', async () => {
    guardMock.mockResolvedValueOnce({ ok: true, session: { user: { userId: ACTOR_ID } } });
