import { describe, expect, it, vi, beforeEach } from 'vitest';

vi.mock('next/cache', () => ({
  revalidatePath: vi.fn(),
}));

const mockRequirePatientApiBusinessAccess = vi.hoisted(() => vi.fn());
vi.mock('@/app-layer/guards/requireRole', () => ({
  requirePatientApiBusinessAccess: mockRequirePatientApiBusinessAccess,
}));

const checkAuthConfirmRateLimitMock = vi.hoisted(() => vi.fn());
vi.mock('@/modules/auth/authConfirmRateLimit', () => ({
  AUTH_CONFIRM_RATE_LIMIT_SEC: 600,
  checkAuthConfirmRateLimit: (...args: unknown[]) => checkAuthConfirmRateLimitMock(...args),
}));

import * as authService from '@/modules/auth/service';
import { POST } from './route';

const purgeMock = vi.fn().mockResolvedValue(undefined);
const confirmPhoneAuthMock = vi.fn();

vi.mock('@/app-layer/di/buildAppDeps', () => ({
  buildAppDeps: () => ({
    auth: {
      confirmPhoneAuth: (...args: unknown[]) => confirmPhoneAuthMock(...args),
    },
    diaries: {
      purgeAllDiaryDataForUser: (uid: string) => purgeMock(uid),
    },
  }),
}));

describe('POST /api/patient/diary/purge', () => {
  beforeEach(() => {
    purgeMock.mockClear();
    confirmPhoneAuthMock.mockReset();
    checkAuthConfirmRateLimitMock.mockReset();
    checkAuthConfirmRateLimitMock.mockResolvedValue({ limited: false });
    mockRequirePatientApiBusinessAccess.mockResolvedValue({
      ok: true,
      session: {
        user: {
          userId: 'u-1',
          role: 'client',
          displayName: 'Test',
          phone: '+79990001122',
          bindings: {},
        },
        issuedAt: 0,
        expiresAt: 9999999999,
      },
    });
    vi.spyOn(authService, 'clearDiaryPurgeReauth').mockResolvedValue(undefined);
    confirmPhoneAuthMock.mockResolvedValue({
      ok: true,
      user: {
        userId: 'u-1',
        role: 'client' as const,
        displayName: 'Test',
        phone: '+79990001122',
        bindings: {},
      },
      redirectTo: '/app/patient',
    });
  });

  it('returns 429 rate_limited (same shape as too_many_attempts) when the per-IP limit trips, before the auth gate', async () => {
    checkAuthConfirmRateLimitMock.mockResolvedValueOnce({ limited: true, reason: 'rate_limited' });
    const res = await POST(
      new Request('http://localhost/api/patient/diary/purge', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ challengeId: 'c1', code: '123456' }),
      }),
    );
    expect(res.status).toBe(429);
    expect(res.headers.get('Retry-After')).toBe('600');
    await expect(res.json()).resolves.toEqual({
      ok: false,
      error: 'rate_limited',
      retryAfterSeconds: 600,
    });
    expect(mockRequirePatientApiBusinessAccess).not.toHaveBeenCalled();
    expect(confirmPhoneAuthMock).not.toHaveBeenCalled();
  });

  it('returns 503 proxy_configuration when the per-IP key cannot be resolved', async () => {
    checkAuthConfirmRateLimitMock.mockResolvedValueOnce({
      limited: true,
      reason: 'proxy_configuration',
    });
    const res = await POST(
      new Request('http://localhost/api/patient/diary/purge', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ challengeId: 'c1', code: '123456' }),
      }),
    );
    expect(res.status).toBe(503);
    await expect(res.json()).resolves.toEqual({ ok: false, error: 'proxy_configuration' });
  });

  it('returns 400 when body invalid', async () => {
    const res = await POST(
      new Request('http://localhost/api/patient/diary/purge', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({}),
      }),
    );
    expect(res.status).toBe(400);
  });

  it('purges when OTP confirms same user', async () => {
    const res = await POST(
      new Request('http://localhost/api/patient/diary/purge', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ challengeId: 'c1', code: '123456' }),
      }),
    );
    expect(res.status).toBe(200);
    expect(purgeMock).toHaveBeenCalledWith('u-1');
    expect(authService.clearDiaryPurgeReauth).toHaveBeenCalled();
  });

  it('returns 403 when user id mismatch after OTP', async () => {
    confirmPhoneAuthMock.mockResolvedValue({
      ok: true,
      user: {
        userId: 'other',
        role: 'client' as const,
        displayName: 'X',
        phone: '+79990001122',
        bindings: {},
      },
      redirectTo: '/app/patient',
    });
    const res = await POST(
      new Request('http://localhost/api/patient/diary/purge', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ challengeId: 'c1', code: '123456' }),
      }),
    );
    expect(res.status).toBe(403);
    expect(purgeMock).not.toHaveBeenCalled();
  });
});

src/app/api/admin/booking-engine/working.source:
import { describe, expect, it, vi, beforeEach } from 'vitest';

const requireAdminBookingEngineMock = vi.hoisted(() => vi.fn());
const listScheduleTemplatesMock = vi.hoisted(() => vi.fn());
const createScheduleTemplateMock = vi.hoisted(() => vi.fn());
const deleteScheduleTemplateMock = vi.hoisted(() => vi.fn());
const applyScheduleTemplateMock = vi.hoisted(() => vi.fn());
const principalState = vi.hoisted(() => ({ inside: false }));
const withDoctorWorkspacePrincipalMock = vi.hoisted(() =>
  vi.fn(
    async <T>(_workspace: { organizationId: string }, _source: string, fn: () => Promise<T>) => {
      principalState.inside = true;
      try {
        return await fn();
      } finally {
        principalState.inside = false;
      }
    },
  ),
);

vi.mock('../_requireAdminBookingEngine', () => ({
  requireAdminBookingEngine: requireAdminBookingEngineMock,
}));

vi.mock('@/app-layer/di/buildAppDeps', () => ({
  buildAppDeps: () => ({
    bookingScheduling: {
      listScheduleTemplates: listScheduleTemplatesMock,
      createScheduleTemplate: createScheduleTemplateMock,
      deleteScheduleTemplate: deleteScheduleTemplateMock,
      applyScheduleTemplate: applyScheduleTemplateMock,
    },
  }),
}));

vi.mock('@/app-layer/principal/withOrganizationPrincipal', () => ({
  withDoctorWorkspacePrincipal: withDoctorWorkspacePrincipalMock,
}));

import { GET, POST, DELETE } from './route';

const ORG = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
const TMPL = 'cccccccc-cccc-4ccc-8ccc-cccccccccccc';

describe('/api/admin/booking-engine/working-schedule-templates', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    principalState.inside = false;
  });

  describe('GET', () => {
    it('returns 401 when not authenticated', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({
        ok: false,
        response: Response.json({ ok: false, error: 'unauthorized' }, { status: 401 }),
      });
      const res = await GET(
        new Request('http://localhost/api/admin/booking-engine/working-schedule-templates'),
      );
      expect(res.status).toBe(401);
    });

    it('returns rows', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({ ok: true, ctx: { organizationId: ORG } });
      listScheduleTemplatesMock.mockResolvedValue([{ id: TMPL, name: 'Стандарт' }]);
      const res = await GET(
        new Request('http://localhost/api/admin/booking-engine/working-schedule-templates'),
      );
      const json = (await res.json()) as { ok: boolean; rows: unknown[] };
      expect(res.status).toBe(200);
      expect(json.ok).toBe(true);
      expect(json.rows).toHaveLength(1);
      expect(listScheduleTemplatesMock).toHaveBeenCalledWith(ORG);
      expect(withDoctorWorkspacePrincipalMock).not.toHaveBeenCalled();
    });
  });

  describe('POST (create)', () => {
    it('returns 401 when not authenticated', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({
        ok: false,
        response: Response.json({ ok: false, error: 'unauthorized' }, { status: 401 }),
      });
      const res = await POST(
        new Request('http://localhost/api/admin/booking-engine/working-schedule-templates', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: 'Test', startMinute: 540, endMinute: 1080 }),
        }),
      );
      expect(res.status).toBe(401);
    });

    it('creates a template', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({ ok: true, ctx: { organizationId: ORG } });
      createScheduleTemplateMock.mockImplementation(async () => {
        expect(principalState.inside).toBe(true);
        return { id: TMPL, name: 'Стандарт' };
      });
      const res = await POST(
        new Request('http://localhost/api/admin/booking-engine/working-schedule-templates', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: 'Стандарт', startMinute: 540, endMinute: 1080 }),
        }),
      );
      const json = (await res.json()) as { ok: boolean; row: { id: string } };
      expect(res.status).toBe(200);
      expect(json.ok).toBe(true);
      expect(createScheduleTemplateMock).toHaveBeenCalledWith(
        expect.objectContaining({
          organizationId: ORG,
          name: 'Стандарт',
          startMinute: 540,
          endMinute: 1080,
        }),
      );
      expect(withDoctorWorkspacePrincipalMock).toHaveBeenCalledWith(
        expect.objectContaining({ organizationId: ORG }),
        'admin.booking-engine.working-schedule-templates.create',
        expect.any(Function),
      );
    });

    it('rejects startMinute >= endMinute', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({ ok: true, ctx: { organizationId: ORG } });
      const res = await POST(
        new Request('http://localhost/api/admin/booking-engine/working-schedule-templates', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: 'Плохой', startMinute: 600, endMinute: 540 }),
        }),
      );
      expect(res.status).toBe(400);
      expect(createScheduleTemplateMock).not.toHaveBeenCalled();
    });

    it('rejects missing name', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({ ok: true, ctx: { organizationId: ORG } });
      const res = await POST(
        new Request('http://localhost/api/admin/booking-engine/working-schedule-templates', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ startMinute: 540, endMinute: 1080 }),
        }),
      );
      expect(res.status).toBe(400);
    });
  });

  describe('POST (apply)', () => {
    it('applies template to dates', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({ ok: true, ctx: { organizationId: ORG } });
      applyScheduleTemplateMock.mockImplementation(async () => {
        expect(principalState.inside).toBe(true);
        return [];
      });
      const res = await POST(
        new Request(
          'http://localhost/api/admin/booking-engine/working-schedule-templates?action=apply',
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ templateId: TMPL, dates: ['2026-06-10', '2026-06-11'] }),
          },
        ),
      );
      const json = (await res.json()) as { ok: boolean };
      expect(res.status).toBe(200);
      expect(json.ok).toBe(true);
      expect(applyScheduleTemplateMock).toHaveBeenCalledWith(
        expect.objectContaining({
          organizationId: ORG,
          templateId: TMPL,
          dates: ['2026-06-10', '2026-06-11'],
        }),
      );
      expect(withDoctorWorkspacePrincipalMock).toHaveBeenCalledWith(
        expect.objectContaining({ organizationId: ORG }),
        'admin.booking-engine.working-schedule-templates.apply',
        expect.any(Function),
      );
    });

    it('returns 400 when templateId missing for apply', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({ ok: true, ctx: { organizationId: ORG } });
      const res = await POST(
        new Request(
          'http://localhost/api/admin/booking-engine/working-schedule-templates?action=apply',
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ dates: ['2026-06-10'] }),
          },
        ),
      );
      expect(res.status).toBe(400);
      expect(applyScheduleTemplateMock).not.toHaveBeenCalled();
      expect(withDoctorWorkspacePrincipalMock).not.toHaveBeenCalled();
    });
  });

  describe('DELETE', () => {
    it('returns 400 when id missing', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({ ok: true, ctx: { organizationId: ORG } });
      const res = await DELETE(
        new Request('http://localhost/api/admin/booking-engine/working-schedule-templates'),
      );
      expect(res.status).toBe(400);
    });

    it('deletes template by id', async () => {
      requireAdminBookingEngineMock.mockResolvedValue({ ok: true, ctx: { organizationId: ORG } });
      deleteScheduleTemplateMock.mockImplementation(async () => {
        expect(principalState.inside).toBe(true);
      });
      const res = await DELETE(
        new Request(
          `http://localhost/api/admin/booking-engine/working-schedule-templates?id=${TMPL}`,
        ),
      );
      const json = (await res.json()) as { ok: boolean };
      expect(res.status).toBe(200);
      expect(json.ok).toBe(true);
      expect(deleteScheduleTemplateMock).toHaveBeenCalledWith(TMPL, ORG);
      expect(withDoctorWorkspacePrincipalMock).toHaveBeenCalledWith(
        expect.objectContaining({ organizationId: ORG }),
        'admin.booking-engine.working-schedule-templates.delete',
        expect.any(Function),
      );
    });
  });
});

