import { beforeEach, describe, expect, it, vi } from 'vitest';
import { getCurrentDbPrincipalOrganizationId } from '@bersoncare/db-principal';

const resolvePublicBookingOrganizationMock = vi.hoisted(() => vi.fn());
const resolveCanonicalInPersonContextMock = vi.hoisted(() => vi.fn());
const getBranchMock = vi.hoisted(() => vi.fn());
const getServiceMock = vi.hoisted(() => vi.fn());
const getSlotsMock = vi.hoisted(() => vi.fn());
const resolveOrganizationIdBySlugMock = vi.hoisted(() => vi.fn());
const warnMock = vi.hoisted(() => vi.fn());

vi.mock('@/app-layer/logging/logger', () => ({
  logger: { warn: warnMock, error: vi.fn() },
}));

vi.mock('@/app-layer/di/buildAppDeps', () => ({
  buildAppDeps: () => ({
    patientBooking: { getSlots: getSlotsMock },
    clinicDirectory: { resolveOrganizationIdBySlug: resolveOrganizationIdBySlugMock },
    bookingEngine: {
      catalog: { getBranch: getBranchMock },
      services: { getService: getServiceMock },
    },
    bookingScheduling: {
      resolvePublicBookingOrganization: resolvePublicBookingOrganizationMock,
      resolveCanonicalInPersonContext: resolveCanonicalInPersonContextMock,
    },
  }),
}));

import { GET } from './route';

const ORG_ID = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
const OTHER_ORG_ID = 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaab';
const BRANCH_ID = 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
const SERVICE_ID = 'cccccccc-cccc-4ccc-8ccc-cccccccccccc';
let organizationSeenByTenantRead: string | undefined;

describe('GET /api/booking/public/slots', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    organizationSeenByTenantRead = undefined;
    resolvePublicBookingOrganizationMock.mockResolvedValue(ORG_ID);
    resolveOrganizationIdBySlugMock.mockResolvedValue(ORG_ID);
    getBranchMock.mockImplementation(async () => {
      organizationSeenByTenantRead = getCurrentDbPrincipalOrganizationId();
      return { id: BRANCH_ID, organizationId: ORG_ID };
    });
    getServiceMock.mockResolvedValue({ id: SERVICE_ID, organizationId: ORG_ID });
    resolveCanonicalInPersonContextMock.mockResolvedValue({
      organizationId: ORG_ID,
      branchId: BRANCH_ID,
      serviceId: SERVICE_ID,
    });
    getSlotsMock.mockResolvedValue([{ date: '2026-07-17', slots: [] }]);
  });

  it('derives the tenant and passes only canonical keys', async () => {
    const response = await GET(
      new Request(
        `http://localhost/api/booking/public/slots?type=in_person&branchId=${BRANCH_ID}&serviceId=${SERVICE_ID}&orgSlug=clinic-a`,
      ),
    );
    expect(response.status).toBe(200);
    expect(resolvePublicBookingOrganizationMock).toHaveBeenCalledWith({
      branchId: BRANCH_ID,
      serviceId: SERVICE_ID,
    });
    expect(getSlotsMock).toHaveBeenCalledWith(
      expect.objectContaining({
        organizationId: ORG_ID,
        branchId: BRANCH_ID,
        serviceId: SERVICE_ID,
      }),
    );
  });

  it('rejects a legacy-id-only request before booking reads', async () => {
    const response = await GET(
      new Request(
        'http://localhost/api/booking/public/slots?type=in_person&branchServiceId=dddddddd-dddd-4ddd-8ddd-dddddddddddd&orgSlug=clinic-a',
      ),
    );
    expect(response.status).toBe(400);
    expect(getSlotsMock).not.toHaveBeenCalled();
  });

  it('derives org first, then performs tenant reads under that explicit org', async () => {
    const response = await GET(
      new Request(
        `http://localhost/api/booking/public/slots?type=in_person&branchId=${BRANCH_ID}&serviceId=${SERVICE_ID}&orgSlug=clinic-a`,
      ),
    );

    expect(response.status).toBe(200);
    expect(resolvePublicBookingOrganizationMock.mock.invocationCallOrder[0]).toBeLessThan(
      getBranchMock.mock.invocationCallOrder[0]!,
    );
    expect(organizationSeenByTenantRead).toBe(ORG_ID);
  });

  it('keeps distinct private tenant-resolution failures wire-identical and logs their reasons', async () => {
    resolvePublicBookingOrganizationMock.mockResolvedValue(null);
    const emptyResolverResponse = await GET(
      new Request(
        `http://localhost/api/booking/public/slots?type=in_person&branchId=${BRANCH_ID}&serviceId=${SERVICE_ID}&orgSlug=clinic-a`,
      ),
    );
    resolveOrganizationIdBySlugMock.mockResolvedValue(null);
    const unknownSlugResponse = await GET(
      new Request(
        `http://localhost/api/booking/public/slots?type=in_person&branchId=${BRANCH_ID}&serviceId=${SERVICE_ID}&orgSlug=clinic-a`,
      ),
    );

    expect(emptyResolverResponse.status).toBe(400);
    await expect(emptyResolverResponse.json()).resolves.toEqual({
      ok: false,
      error: 'ambiguous_booking_tenant',
    });
    expect(unknownSlugResponse.status).toBe(400);
    await expect(unknownSlugResponse.json()).resolves.toEqual({
      ok: false,
      error: 'ambiguous_booking_tenant',
    });
    expect(warnMock).toHaveBeenNthCalledWith(
      1,
      expect.objectContaining({
        reason: 'public_resolver_empty',
        branchId: BRANCH_ID,
        serviceId: SERVICE_ID,
        orgSlug: 'clinic-a',
      }),
      expect.stringContaining('in-person booking resolution refused'),
    );
    expect(warnMock).toHaveBeenNthCalledWith(
      2,
      expect.objectContaining({
        reason: 'slug_unknown',
        branchId: BRANCH_ID,
        serviceId: SERVICE_ID,
        orgSlug: 'clinic-a',
      }),
      expect.stringContaining('in-person booking resolution refused'),
    );
    expect(getBranchMock).not.toHaveBeenCalled();
    expect(getSlotsMock).not.toHaveBeenCalled();
  });

  it('denies clinic-A URLs carrying valid clinic-B booking ids before tenant reads', async () => {
    resolveOrganizationIdBySlugMock.mockResolvedValue(ORG_ID);
    resolvePublicBookingOrganizationMock.mockResolvedValue(OTHER_ORG_ID);

    const response = await GET(
      new Request(
        `http://localhost/api/booking/public/slots?type=in_person&branchId=${BRANCH_ID}&serviceId=${SERVICE_ID}&orgSlug=clinic-a`,
      ),
    );

    expect(response.status).toBe(400);
    expect(await response.json()).toMatchObject({ ok: false, error: 'ambiguous_booking_tenant' });
    expect(getBranchMock).not.toHaveBeenCalled();
    expect(getSlotsMock).not.toHaveBeenCalled();
  });

  it('keeps generic /book requests without an organization slug fail-closed', async () => {
    const response = await GET(
      new Request(
        `http://localhost/api/booking/public/slots?type=in_person&branchId=${BRANCH_ID}&serviceId=${SERVICE_ID}`,
      ),
    );

    expect(response.status).toBe(400);
    expect(await response.json()).toMatchObject({ ok: false, error: 'ambiguous_booking_tenant' });
    expect(resolvePublicBookingOrganizationMock).not.toHaveBeenCalled();
    expect(getSlotsMock).not.toHaveBeenCalled();
  });
});

src/app/api/admin/audit-log/route.test.t.source:
import { beforeEach, describe, expect, it, vi } from 'vitest';

const {
  requireAdminModeSessionMock,
  requireDoctorWorkspaceApiContextMock,
  requirePlatformOperationsApiContextMock,
  withDoctorWorkspacePrincipalMock,
  getPoolMock,
  listAdminAuditLogMock,
  countOpenAutoMergeConflictsMock,
} = vi.hoisted(() => ({
  requireAdminModeSessionMock: vi.fn(),
  requireDoctorWorkspaceApiContextMock: vi.fn(),
  requirePlatformOperationsApiContextMock: vi.fn(),
  withDoctorWorkspacePrincipalMock: vi.fn((_ctx: unknown, fn: () => unknown) => fn()),
  getPoolMock: vi.fn(() => ({})),
  listAdminAuditLogMock: vi.fn(),
  countOpenAutoMergeConflictsMock: vi.fn(),
}));

vi.mock('@/modules/auth/requireAdminMode', () => ({
  requireAdminModeSession: requireAdminModeSessionMock,
}));

vi.mock('@/app-layer/guards/requireRole', () => ({
  requireDoctorWorkspaceApiContext: requireDoctorWorkspaceApiContextMock,
  requirePlatformOperationsApiContext: requirePlatformOperationsApiContextMock,
}));

vi.mock('@/app-layer/guards/doctorWorkspacePrincipal', () => ({
  withDoctorWorkspacePrincipal: (
    ctx: unknown,
    sourceOrFn: string | (() => unknown),
    maybeFn?: () => unknown,
  ) => {
    const fn = typeof sourceOrFn === 'function' ? sourceOrFn : maybeFn;
    if (!fn) throw new Error('principal_callback_required');
    return withDoctorWorkspacePrincipalMock(ctx, fn);
  },
}));

vi.mock('@/app-layer/db/client', () => ({
  getPool: getPoolMock,
}));

vi.mock('@/app-layer/admin/auditLog', () => ({
  listAdminAuditLog: listAdminAuditLogMock,
  countOpenAutoMergeConflicts: countOpenAutoMergeConflictsMock,
}));

import { GET } from './route';

describe('GET /api/admin/audit-log', () => {
  beforeEach(() => {
    requireAdminModeSessionMock.mockReset();
    requireDoctorWorkspaceApiContextMock.mockReset();
    requirePlatformOperationsApiContextMock.mockReset();
    withDoctorWorkspacePrincipalMock.mockClear();
    getPoolMock.mockClear();
    listAdminAuditLogMock.mockReset();
    countOpenAutoMergeConflictsMock.mockReset();
    countOpenAutoMergeConflictsMock.mockResolvedValue(0);
    requireDoctorWorkspaceApiContextMock.mockResolvedValue({
      ok: true,
      ctx: { organizationId: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' },
    });
    requirePlatformOperationsApiContextMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' }, adminMode: true },
    });
  });

  it('returns 403 when not admin mode', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: false,
      response: new Response(JSON.stringify({ ok: false }), { status: 403 }),
    });
    const res = await GET(new Request('http://localhost/api/admin/audit-log'));
    expect(res.status).toBe(403);
  });

  it('returns 400 on invalid date query', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' } },
    });
    const res = await GET(new Request('http://localhost/api/admin/audit-log?from=not-a-date'));
    expect(res.status).toBe(400);
  });

  it('returns workspace gate response before audit reads', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' } },
    });
    requireDoctorWorkspaceApiContextMock.mockResolvedValueOnce({
      ok: false,
      response: new Response(
        JSON.stringify({ ok: false, error: 'doctor_workspace_membership_required' }),
        {
          status: 403,
        },
      ),
    });
    const res = await GET(new Request('http://localhost/api/admin/audit-log?page=1'));
    expect(res.status).toBe(403);
    expect(listAdminAuditLogMock).not.toHaveBeenCalled();
    expect(countOpenAutoMergeConflictsMock).not.toHaveBeenCalled();
  });

  it('returns 400 when from is after to', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' } },
    });
    const res = await GET(
      new Request('http://localhost/api/admin/audit-log?from=2026-04-10&to=2026-04-01'),
    );
    expect(res.status).toBe(400);
  });

  it('returns list when authorized', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' } },
    });
    listAdminAuditLogMock.mockResolvedValue({
      items: [],
      total: 0,
      page: 1,
      limit: 50,
    });
    const res = await GET(new Request('http://localhost/api/admin/audit-log?page=1&limit=10'));
    expect(res.status).toBe(200);
    const body = (await res.json()) as {
      ok: boolean;
      total: number;
      openAutoMergeConflictCount: number;
    };
    expect(body.ok).toBe(true);
    expect(body.total).toBe(0);
    expect(body.openAutoMergeConflictCount).toBe(0);
    expect(listAdminAuditLogMock).toHaveBeenCalled();
    expect(countOpenAutoMergeConflictsMock).toHaveBeenCalled();
    expect(withDoctorWorkspacePrincipalMock).toHaveBeenCalledWith(
      expect.objectContaining({ organizationId: 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' }),
      expect.any(Function),
    );
  });

  it('passes excludeSystemHealth to list when query flag set', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' } },
    });
    listAdminAuditLogMock.mockResolvedValue({
      items: [],
      total: 0,
      page: 1,
      limit: 50,
    });
    const res = await GET(
      new Request('http://localhost/api/admin/audit-log?excludeSystemHealth=1'),
    );
    expect(res.status).toBe(200);
    expect(listAdminAuditLogMock).toHaveBeenCalledWith(
      expect.anything(),
      expect.objectContaining({ excludeActionPrefix: 'system_health_' }),
    );
  });

  it('returns 400 when excludeSystemHealth and systemHealthOnly both set', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' } },
    });
    const res = await GET(
      new Request('http://localhost/api/admin/audit-log?excludeSystemHealth=1&systemHealthOnly=1'),
    );
    expect(res.status).toBe(400);
    expect(listAdminAuditLogMock).not.toHaveBeenCalled();
  });

  it('passes systemHealthScopeOnly when systemHealthOnly=1', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' } },
    });
    listAdminAuditLogMock.mockResolvedValue({
      items: [],
      total: 0,
      page: 1,
      limit: 50,
    });
    const res = await GET(new Request('http://localhost/api/admin/audit-log?systemHealthOnly=1'));
    expect(res.status).toBe(200);
    expect(listAdminAuditLogMock).toHaveBeenCalledWith(
      expect.anything(),
      expect.objectContaining({ systemHealthScopeOnly: true }),
    );
  });

  it('passes involvesPlatformUserId to list when valid uuid', async () => {
    requireAdminModeSessionMock.mockResolvedValue({
      ok: true,
      session: { user: { userId: 'a1', role: 'admin' } },
    });
    listAdminAuditLogMock.mockResolvedValue({
      items: [],
      total: 0,
      page: 1,
      limit: 50,
    });
    const uid = 'cccccccc-cccc-4ccc-8ccc-cccccccccccc';
    const res = await GET(
      new Request(
        `http://localhost/api/admin/audit-log?involvesPlatformUserId=${encodeURIComponent(uid)}`,
      ),
    );
    expect(res.status).toBe(200);
    expect(listAdminAuditLogMock).toHaveBeenCalledWith(
      expect.anything(),
      expect.objectContaining({ involvesPlatformUserId: uid }),
    );
  });

  describe('global admin (platform.operations)', () => {
    it('uses requirePlatformOperationsApiContext, never requireDoctorWorkspaceApiContext, and skips org scoping', async () => {
      requireAdminModeSessionMock.mockResolvedValue({
        ok: true,
        session: { user: { userId: 'a1', role: 'admin' }, adminMode: true },
      });
      listAdminAuditLogMock.mockResolvedValue({ items: [], total: 0, page: 1, limit: 50 });
      const res = await GET(new Request('http://localhost/api/admin/audit-log?page=1'));
      expect(res.status).toBe(200);
      expect(requirePlatformOperationsApiContextMock).toHaveBeenCalled();
      expect(requireDoctorWorkspaceApiContextMock).not.toHaveBeenCalled();
      expect(withDoctorWorkspacePrincipalMock).not.toHaveBeenCalled();
      expect(listAdminAuditLogMock).toHaveBeenCalled();
    });

    it("returns the platform gate's response when the global admin is restricted (e.g. 2FA)", async () => {
      requireAdminModeSessionMock.mockResolvedValue({
        ok: true,
        session: { user: { userId: 'a1', role: 'admin' }, adminMode: true },
      });
      requirePlatformOperationsApiContextMock.mockResolvedValueOnce({
        ok: false,
        response: new Response(JSON.stringify({ ok: false, error: 'forbidden' }), { status: 403 }),
      });
      const res = await GET(new Request('http://localhost/api/admin/audit-log?page=1'));
      expect(res.status).toBe(403);
      expect(getPoolMock).not.toHaveBeenCalled();
      expect(listAdminAuditLogMock).not.toHaveBeenCalled();
    });
  });
});

