import { describe, expect, it, vi, beforeEach } from 'vitest';

const googleMocks = vi.hoisted(() => ({
  getGoogleClientId: vi.fn().mockResolvedValue('cid'),
  getGoogleClientSecret: vi.fn().mockResolvedValue('csec'),
