    getGoogleClientSecret: googleMocks.getGoogleClientSecret,
    getGoogleRedirectUri: googleMocks.getGoogleRedirectUri,
    isGoogleCalendarPlatformAvailable: googleMocks.isGoogleCalendarPlatformAvailable,
