  it('createPgTreatmentProgramItemSnapshotPort buildSnapshot enriches exercise media from media_files', async () => {
    drizzleSnapshotState.exerciseRow = {
      id: EXERCISE_ID,
      title: 'Присед',
      description: null,
      contraindications: null,
      difficulty110: 5,
