      ctx: { organizationId: ORG, session: { user: { userId: 'u1' } } },
    });
    listStaffProductsMock.mockResolvedValue([product]);
    upsertProductMock.mockImplementation(async () => {
      expect(principalState.inside).toBe(true);
      return product;
