        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ filename: 'photo.jpg', mimeType: 'image/jpeg', size: 1024 }),
      }),
      context,
    );
    expect(response.status).toBe(415);
    expect(resolveMock).not.toHaveBeenCalled();
  });
});

