    memberships: membershipsModuleEnabled.value
      ? {
          recalcPastSessionsForPackageDbPhase: recalcPastSessionsForPackageDbPhaseMock,
          refreshRecalcPastSessionsCalendar: refreshRecalcPastSessionsCalendarMock,
        }
      : null,
  }),
