    expect(res.status).toBe(200);
    expect(withDoctorWorkspacePrincipalMock).toHaveBeenCalledWith(
      workspaceCtx,
      expect.any(Function),
    );
    expect(expandMock).toHaveBeenCalledWith(
      expect.objectContaining({
        instanceId: INSTANCE_ID,
        stageId: STAGE_ID,
        complexTemplateId: COMPLEX_ID,
        groupId: GROUP_ID,
        actorId: DOCTOR_ID,
      }),
    );
  });
});

