      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({}),
    });
    const res = await POST(req);
    expect(res.status).toBe(200);
    expect(mockTrySetInitial).toHaveBeenCalledWith(SESSION.user.userId, null);
  });

  it('POST returns 401 when gate fails', async () => {
