    const res = await GET(
      new Request('http://localhost/api/doctor/comments/patients/p/exercises'),
      params('not-a-uuid'),
    );

    expect(res.status).toBe(400);
    expect(getClientIdentityForOrganizationMock).not.toHaveBeenCalled();
  });
});

