      savePatientHomeRepeatCooldownsAction({ warmupRepeatMinutes: 30, planItemRepeatMinutes: 45 }),
    ).resolves.toEqual({ ok: true });
    expect(updateSettingMock).toHaveBeenCalledTimes(2);
