import { GET } from './route';

const patientClientSession = {
  user: { userId: 'u1', role: 'client' as const, phone: '+79990001122' },
};

requirePatientBookingTrustedPhoneAccessMock.mockImplementation(
  async (options?: { returnPath?: string }) => {
